def check_source(source,name):
    tree=ast.parse(source,filename=name)
    compile(tree,name,'exec')
    if any(line.endswith((' ','\t')) for line in source.splitlines()):
        raise ValueError('Trailing source whitespace: '+name)
    for node in ast.walk(tree):
        if isinstance(node,ast.Dict):
            keys=[ast.literal_eval(k) for k in node.keys if isinstance(k,ast.Constant)]
            if len(keys)!=len(set(keys)):
                raise ValueError('Duplicate literal dictionary keys: '+name)
    return tree


def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--source-directory',type=Path,required=True)
    p.add_argument('--out',type=Path,required=True)
    args=p.parse_args()
    if args.out.exists():
        raise ValueError('Use a fresh source-only output directory')
    path=args.source_directory/PLAN['parent_filename']
    raw=path.read_bytes()
    if len(raw)!=PLAN['parent_bytes'] or hashlib.sha256(raw).hexdigest()!=PLAN['parent_sha256']:
        raise ValueError('The complete immutable105289 parent source changed')
    patches=PLAN['exact_byte_patches']
    previous=0
    for item in patches:
        start,end=item['start'],item['end']
        if not previous<=start<=end<=len(raw):
            raise ValueError('The complete exact source edits overlap or escape the parent')
        if hashlib.sha256(raw[start:end]).hexdigest()!=item['parent_slice_sha256']:
            raise ValueError('One exact parent source slice differs')
        previous=end
    result=raw
    for item in reversed(patches):
        result=result[:item['start']]+item['complete_replacement'].encode()+result[item['end']:]
    if len(result)!=PLAN['output_bytes'] or hashlib.sha256(result).hexdigest()!=PLAN['output_sha256']:
        raise ValueError('The complete reconstructed producer differs from its declared body')
    hb=HELPER.encode()
    if len(hb)!=PLAN['helper_bytes'] or hashlib.sha256(hb).hexdigest()!=PLAN['helper_sha256']:
        raise ValueError('The complete independent pure input binder differs')
    old=check_source(raw.decode(),PLAN['parent_filename'])
    new=check_source(result.decode(),PLAN['output_filename'])
    check_source(HELPER,PLAN['helper_filename'])
    of={n.name:ast.dump(n,include_attributes=False) for n in old.body if isinstance(n,ast.FunctionDef)}
    nf={n.name:ast.dump(n,include_attributes=False) for n in new.body if isinstance(n,ast.FunctionDef)}
    preserved=('read_public_step','exact_node_definitions','counted_tail_class','compare_member','array_record','verify_projection_origin')
    for name in preserved:
        if of[name]!=nf[name]:
            raise ValueError('Original complete scalar/address source body changed: '+name)
    begin="    deep_module = modules['deep_scalar']\n"
    end='    target=fixed_target_definition('
    old_text,new_text=raw.decode(),result.decode()
    if old_text[old_text.index(begin):old_text.index(end)]!=new_text[new_text.index(begin):new_text.index(end)]:
        raise ValueError('The complete original reconstruction/whole-dc5 block changed')
    args.out.mkdir(parents=True)
    for name,data in ((PLAN['helper_filename'],hb),(PLAN['output_filename'],result)):
        (args.out/name).write_bytes(data)
    lock=dict(schema='complete-run09-public-input-source-construction-v1',
        parent_sha256=PLAN['parent_sha256'],complete_parent_source=True,
        complete_output_files=[dict(filename=name,bytes=len(data),sha256=hashlib.sha256(data).hexdigest())
            for name,data in ((PLAN['helper_filename'],hb),(PLAN['output_filename'],result))],
        exact_source_patch_count=len(patches),original_functions_retained=list(preserved),
        original_complete_scalar_reconstruction_and_carrier_save_byte_identical=True,
        actual_AST_and_compile=True,scientific_imports_or_execution=False)
    (args.out/'source-locks.json').write_text(json.dumps(lock,indent=2)+'\n')
    print(json.dumps(lock,sort_keys=True))


